using System;
public class ModWithKills : Item
{
	protected Enemy currentEnemy;
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	public virtual void SetModStatus(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			SetExtraMods(givenStatus);
			Player player = parentPlayer;
			player.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Remove(player.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.absEnemyKillEventHandlers = (Player.AbsEnemyKillEventHandler)Delegate.Combine(player2.absEnemyKillEventHandlers, new Player.AbsEnemyKillEventHandler(OnKillEvent));
			}
		}
	}
	public virtual void SetExtraMods(bool givenStatus)
	{
	}
	public bool IsValidKill(Entity givenEntity, AttackInfo givenInfo)
	{
		currentEnemy = givenEntity as Enemy;
		if (currentEnemy == null || (currentEnemy is Blob && ((Blob)currentEnemy).isMini))
		{
			return false;
		}
		return !currentEnemy.summoned && currentEnemy.parentSummoner == null;
	}
	public virtual void OnKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (IsValidKill(givenEntity, givenInfo))
		{
			HandleKillEvent(givenEntity, givenInfo);
		}
	}
	public virtual void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
	}
}
